import SwiftUI
import ToeflyCore

// Design tokens with the same names as the web theme (docs/07-ux-ui.md §2.12). Colors live in
// Assets.xcassets/Colors as color sets with Any/Dark variants, generated by scripts/generate-color-assets.py.

extension Color {
    // swiftlint:disable:next type_name
    enum toefly {
        // brand scale
        static let brand50 = Color("brand50"), brand100 = Color("brand100"), brand200 = Color("brand200")
        static let brand300 = Color("brand300"), brand400 = Color("brand400"), brand500 = Color("brand500")
        static let brand600 = Color("brand600"), brand700 = Color("brand700"), brand800 = Color("brand800")
        static let brand900 = Color("brand900"), brand950 = Color("brand950")
        // semantic
        static let canvas = Color("canvas"), surface = Color("surface"), surfaceRaised = Color("surfaceRaised")
        static let surfaceTask = Color("surfaceTask"), surfaceSunken = Color("surfaceSunken")
        static let ink = Color("ink"), inkMuted = Color("inkMuted"), inkSubtle = Color("inkSubtle"),
                   inkInverse = Color("inkInverse")
        static let border = Color("border"), borderStrong = Color("borderStrong"),
                   checkboxBorder = Color("checkboxBorder")
        static let accent = Color("brandAccent"), accentSoft = Color("accentSoft"), accentOnSoft = Color("accentOnSoft")
        static let primary = Color("primary"), primaryHover = Color("primaryHover")
        static let link = Color("link"), focusRing = Color("focusRing")
        static let success = Color("success"), successSoft = Color("successSoft")
        static let warning = Color("warning"), warningSoft = Color("warningSoft")
        static let danger = Color("danger"), dangerSoft = Color("dangerSoft"), dangerSolid = Color("dangerSolid")
        static let info = Color("info"), infoSoft = Color("infoSoft"), recording = Color("recording")
        static let ringTrack = Color("ringTrack"), meshCanvas = Color("meshCanvas")
    }

    init(hex: UInt32, opacity: Double = 1) {
        self.init(
            .sRGB,
            red: Double((hex >> 16) & 0xFF) / 255,
            green: Double((hex >> 8) & 0xFF) / 255,
            blue: Double(hex & 0xFF) / 255,
            opacity: opacity,
        )
    }
}

/// Tag colors of the week sections (docs/07-ux-ui.md §2.3).
enum WeekSectionStyle {
    static func tag(_ section: WeekSection) -> (bg: Color, fg: Color) {
        let name = section.rawValue.capitalized
        return (Color("tag\(name)Bg"), Color("tag\(name)Fg"))
    }

    /// SF Symbols of the sections (docs/07-ux-ui.md §2.9).
    static func symbol(_ section: WeekSection) -> String {
        switch section {
        case .reading: "book"
        case .listening: "headphones"
        case .writing: "pencil.line"
        case .speaking: "mic"
        case .vocabulary: "character.book.closed"
        case .grammar: "text.alignleft"
        case .resources: "link"
        }
    }
}

extension ShapeStyle where Self == LinearGradient {
    static var buttonGradient: LinearGradient {
        LinearGradient(
            colors: [Color(hex: 0x0F7D4D), Color(hex: 0x0A8752)],
            startPoint: .topLeading,
            endPoint: .bottomTrailing,
        )
    }

    static var buttonGradientHover: LinearGradient {
        LinearGradient(
            colors: [Color(hex: 0x106B44), Color(hex: 0x0F7D4D)],
            startPoint: .topLeading,
            endPoint: .bottomTrailing,
        )
    }

    static var coverGradient: LinearGradient {
        LinearGradient(
            stops: [
                .init(color: Color(hex: 0x04AC6A), location: 0),
                .init(color: Color(hex: 0x3CC98A), location: 0.5),
                .init(color: Color(hex: 0xA7EBC8), location: 1),
            ],
            startPoint: UnitPoint(x: 0, y: 0.32),
            endPoint: UnitPoint(x: 1, y: 0.68),
        )
    }

    static var barGradient: LinearGradient {
        LinearGradient(colors: [Color(hex: 0x0F7D4D), Color(hex: 0x04AC6A)], startPoint: .leading, endPoint: .trailing)
    }
}

/// ring-gradient: `#0F7D4D → #04AC6A` along the arc, starting at −90° (docs/07-ux-ui.md §2.5).
extension AngularGradient {
    static var ring: AngularGradient {
        AngularGradient(
            colors: [Color(hex: 0x0F7D4D), Color(hex: 0x04AC6A)],
            center: .center,
            startAngle: .degrees(-90),
            endAngle: .degrees(270),
        )
    }
}

enum Radius {
    static let xs: CGFloat = 6, sm: CGFloat = 8, md: CGFloat = 10, base: CGFloat = 12, lg: CGFloat = 16,
               xl: CGFloat = 18, xxl: CGFloat = 22
}

enum Space {
    static let s1: CGFloat = 4, s2: CGFloat = 8, s3: CGFloat = 12, s4: CGFloat = 16, s5: CGFloat = 20, s6: CGFloat = 24
    static let s8: CGFloat = 32, s10: CGFloat = 40, s12: CGFloat = 48
}

enum Motion {
    static let fast = Animation.snappy(duration: 0.15)
    static let base = Animation.smooth(duration: 0.24)
    static let slow = Animation.smooth(duration: 0.36)
    static let progress = Animation.smooth(duration: 0.6)
}

/// Typography tokens on Dynamic Type text styles, so every text scales (docs/07-ux-ui.md §2.7).
extension Font {
    static let toeflyTitle1 = Font.largeTitle.bold()
    static let toeflyTitle2 = Font.title2.weight(.semibold)
    static let toeflyTitle3 = Font.title3.weight(.semibold)
    static let toeflyBodyLarge = Font.body
    static let toeflyBody = Font.callout
    static let toeflyBodyStrong = Font.callout.weight(.semibold)
    static let toeflyCaption = Font.footnote
    static let toeflyMicro = Font.caption2.weight(.semibold)
    static let toeflyOverline = Font.caption.weight(.semibold)
}
